query.query:
SELECT ?place ?placeLabel ?coord (MAX(?pop) AS ?population) WHERE {
  ?place wdt:P17 wd:Q212 ;
         wdt:P1082 ?pop ;
         wdt:P625 ?coord ;
         wdt:P31 ?type .
  VALUES ?type {
    wd:Q12131624 wd:Q5123999 wd:Q515 wd:Q7930989
    wd:Q4100864 wd:Q2989457 wd:Q121366249 wd:Q2514025
    wd:Q21672098 wd:Q532 wd:Q41501164 wd:Q2023000 wd:Q486972
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "uk,en". }
}
GROUP BY ?place ?placeLabel ?coord
ORDER BY DESC(?population)
